class RealTimeMeasurementsPage(NavigatablePage):
    """
    As a class will be called by Performance,
    all operations on RealTime Measurements will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['Performance', 'Performance Management', 'Real-time Measurements']

    def __init__(self, driver, download_checker):
        super(RealTimeMeasurementsPage, self).__init__(driver)
        self._navigation_panel = RealTimeMeasurementsPageNavigationPanel(driver)
        self._view_panel = RealTimeMeasurementsPageViewPanel(driver, download_checker)

    def download_real_time_measurements_counters(self, object_names, timeout):
        """
        Downloading real time measurements counters
        """
        self._navigation_panel.filter_counter(object_names, timeout)
        return self._view_panel.download_real_time_measurements_counters(timeout)

    def get_real_time_measurements(self, object_names, measured_object=None, timeout=60):
        self._navigation_panel.filter_counter(object_names, timeout)
        measurements = self._view_panel.get_real_time_measurements(measured_object, timeout)
        self._navigation_panel.clear_all_selections()
        return measurements

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class RealTimeMeasurementsPageNavigationPanel(NavigationPanel):
    _EXPAND_ICON_XPATH = '//div[@class="tree-list-row-container"]//*[contains(@class, "icon") and @role="button"]'
    _AVAILABLE_OBJECT_FILTER_XPATH = ("//ui-text-input[contains(@a-placeholder, 'Available Object') or "
                                      "contains(@a-placeholder, 'Object name')]//input")
    _OBJECT_NAME = '//highlighter[@text="{}"]'
    _OBJECT_NAME_CHECKBOX = _OBJECT_NAME + '/preceding::label[1]//input'

    def __init__(self, driver):
        super(RealTimeMeasurementsPageNavigationPanel, self).__init__(driver)
        self.common_actions = {
            'clear_all_selections': PerformanceCommonAction(driver).clear_all_selections,
        }
        self.__dict__.update(self.common_actions)

    def filter_counter(self, object_names, timeout):
        if isinstance(object_names, six.string_types):
            object_names = [object_names]
        for name in object_names:
            self._filter_object_name(name, timeout)
            self._select_object(name, timeout)

    def _filter_object_name(self, object_name, timeout):
        self.wait_for_visibility_by_xpath(self._EXPAND_ICON_XPATH, timeout)
        self.insert_text_to_enable_element_and_enter((By.XPATH, self._AVAILABLE_OBJECT_FILTER_XPATH), object_name)
        self.wait_for_text_present_in_attribute(self._AVAILABLE_OBJECT_FILTER_XPATH, "class", "ng-not-empty")

    def _select_object(self, object_name, timeout):
        self.wait_for_visibility_by_xpath(self._OBJECT_NAME.format(object_name), timeout)
        """
        When the object name is mapping to multi ojects, should select all objects.
        Judge the checkbox status before select the object.
        """
        elements = self.driver.find_elements_by_xpath(self._OBJECT_NAME_CHECKBOX.format(object_name))
        for elem in elements:
            status = elem.get_attribute("checked")
            if status != 'true':
                elem.click()


class RealTimeMeasurementsPageViewPanel(ViewPanel):
    _MEASURED_INPUT_XPATH = '//im-counters-main//ui-text-input//input'
    _MEASURED_OBJECT_XPATH = ('//div[@class="im-counters-table-container"]'
                              '//thead//tr[1]//th[contains(@class, "data-column")]')
    _TYPE_XPATH = '//div[@class="im-counters-table-container"]//thead//tr[2]//th[contains(@class, "data-column")]'
    _IM_COUNTER_TBODY_TR_XPATH = '//div[@class="im-counters-table-container"]//tbody//tr'
    _MEASURED_TYPE = ['Voltage', 'Power']

    def __init__(self, driver, download_checker):
        super(RealTimeMeasurementsPageViewPanel, self).__init__(driver)
        self.common_actions = {
            'download_real_time_measurements_counters':
                PerformanceCommonAction(driver, download_checker).export_counters_info_to_csv,
        }
        self.__dict__.update(self.common_actions)

    def _get_real_time_measurements(self, timeout):
        self.wait_for_visibility_by_xpath(self._MEASURED_OBJECT_XPATH, timeout)
        used_columns_mapping_measured_object = []
        for measured_object_th_elem in self.driver.find_elements_by_xpath(self._MEASURED_OBJECT_XPATH):
            num = measured_object_th_elem.get_attribute("colspan")
            used_columns_mapping_measured_object.append((int(num) if num else 1, measured_object_th_elem.text))

        type_names = []
        for type_column_elem in self.driver.find_elements_by_xpath(self._TYPE_XPATH):
            type_names.append(type_column_elem.text)

        counter_info = {}
        for index, tr_elem in enumerate(self.driver.find_elements_by_xpath(self._IM_COUNTER_TBODY_TR_XPATH)):
            time_data = tr_elem.find_element_by_xpath('td[contains(@class, "first-column")]').text
            data = [td.text for td in tr_elem.find_elements_by_xpath('td[contains(@class, "data-column")]')]
            counter_info.update({time_data: data})

        return self._assemble_info(used_columns_mapping_measured_object, type_names, counter_info)

    def _assemble_info(self, used_columns_mapping_measured_object, type_name, counter_info):
        time_key = list(counter_info.keys())
        values = list(counter_info.values())
        value_columns = []
        for index in range(len(values[0])):
            value_column = []
            for value in values:
                value_column.append(value[index])
            assert len(time_key) == len(value_column)
            value_columns.append(value_column)

        counter_info = {}
        for column_used, measured_object in used_columns_mapping_measured_object:
            counter_info.update({measured_object: {}})
            used_type_names = []
            used_value_columns = []
            for _ in range(column_used):
                used_type_names.append(type_name.pop(0))
                used_value_columns.append(value_columns.pop(0))

            for index, value in enumerate(zip(*used_value_columns)):
                counter_info[measured_object].update(
                    {time_key[index]: dict(zip(used_type_names, value))}
                )
        return counter_info

    def get_real_time_measurements(self, measured_object, timeout):
        if measured_object:
            self.insert_text_to_enable_element_and_enter((By.XPATH, self._MEASURED_INPUT_XPATH),
                                                         measured_object,
                                                         timeout)
        return self._get_real_time_measurements(timeout)


class HardWareMonitoringPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Performance', 'Performance Management', 'Hardware Monitoring']

    def __init__(self, driver, download_checker):
        super(HardWareMonitoringPage, self).__init__(driver)
        self._navigation_panel = HardWareMonitoringPageNavigationPanel(driver)
        self._view_panel = HardWareMonitoringPageViewPanel(driver, download_checker)

    def get_hw_monitoring(self, object_name, measured_object=None, timeout=60):
        self._navigation_panel.filter_object(object_name, dist_name=None)
        measurements = self._view_panel.get_hw_monitoring(measured_object, timeout)
        self._navigation_panel.clear_all_selections()
        return measurements

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST


class HardWareMonitoringPageNavigationPanel(NavigationPanel):
    _AVAILABLE_COUNTER_CHECKBOX_XPATH = '//span[contains(text(), "{}")]/../../../preceding-sibling::label//span'

    def __init__(self, driver):
        super(HardWareMonitoringPageNavigationPanel, self).__init__(driver)
        common_action = PerformanceCommonAction(driver)
        self.common_actions = {
            'filter_object': partial(common_action.filter_counter,
                                     counter_checkbox_xpath=self._AVAILABLE_COUNTER_CHECKBOX_XPATH),
            'clear_all_selections': common_action.clear_all_selections
        }
        self.__dict__.update(self.common_actions)


class HardWareMonitoringPageViewPanel(RealTimeMeasurementsPageViewPanel):
    _MEASURED_OBJECT_HEAD_XPATH = '//div[@class="im-counters-table-container"]//thead//tr'
    _MEASURED_OBJECT_BODY_XPATH = '//div[@class="im-counters-table-container"]//tbody//tr'
    _GET_VALUE_SCRIPT = ('return document.querySelector("im-counters-table '
                         'table {} tr:nth-child({}) {}:nth-child({})").innerText')

    def __init__(self, driver, download_checker):
        super(HardWareMonitoringPageViewPanel, self).__init__(driver, download_checker)

    def get_hw_monitoring(self, measured_object, timeout):
        if measured_object:
            self.insert_text_to_enable_element_and_enter((By.XPATH, self._MEASURED_INPUT_XPATH),
                                                         measured_object,
                                                         timeout)
        return self._get_hw_monitoring(timeout)

    def _get_hw_monitoring(self, timeout):
        self.wait_for_visibility_by_xpath(self._MEASURED_OBJECT_HEAD_XPATH, timeout)
        head_line_data = self._get_data_from_table(self._MEASURED_OBJECT_HEAD_XPATH, 'th')
        body_line_data = self._get_data_from_table(self._MEASURED_OBJECT_BODY_XPATH, 'td')

        line_key = []
        line_key.extend([item[0] for item in head_line_data])
        line_key.extend([item[0] for item in body_line_data])

        hw_monitoring = {}

        num = min([len(head_line_data), len(body_line_data[0])])

        for index in range(1, num):
            column_value = []
            column_value.extend([item[index] for item in head_line_data])
            column_value.extend([item[index] for item in body_line_data])
            tmp = dict(zip(line_key, column_value))
            hw_monitoring.update({tmp.pop('Measured object'): tmp})
        return hw_monitoring

    def _get_data_from_table(self, table_tr_xpath, column_label):
        table_part_label = 'tbody' if column_label == 'td' else 'thead'

        tr_elems = self.driver.find_elements_by_xpath(table_tr_xpath)
        colums_elems = tr_elems[0].find_elements_by_xpath(column_label)

        tr_data = []
        for index in range(1, len(tr_elems) + 1):
            th_data = []
            for column in range(1, len(colums_elems) + 1):
                value = self.driver.execute_script(self._GET_VALUE_SCRIPT.format(table_part_label,
                                                                                 index,
                                                                                 column_label,
                                                                                 column))
                th_data.append(value)
            tr_data.append(th_data)
        return tr_data
